// Lấy toàn bộ hội thoại được TẠO trong ngày báo cáo (mặc định: hôm qua, giờ VN)
// trên tất cả page của tài khoản Pancake, kèm nội dung tin nhắn.
const cfg = $('Cấu hình').first().json;
const token = String(cfg.pancake_access_token || '').trim();
if (!token || token.startsWith('DIEN_')) {
  throw new Error('Chưa điền pancake_access_token trong node "Cấu hình".');
}

const VN_OFFSET = 7 * 3600;
let day;
if (/^\d{4}-\d{2}-\d{2}$/.test(String(cfg.ngay_bao_cao || '').trim())) {
  day = String(cfg.ngay_bao_cao).trim();
} else {
  const nowVN = new Date(Date.now() + VN_OFFSET * 1000);
  const y = new Date(Date.UTC(nowVN.getUTCFullYear(), nowVN.getUTCMonth(), nowVN.getUTCDate() - 1));
  day = y.toISOString().slice(0, 10);
}
const since = Math.floor(Date.parse(day + 'T00:00:00Z') / 1000) - VN_OFFSET;
const until = since + 86400;

const MAX_MSG = Number(cfg.so_tin_nhan_toi_da) || 80;
const MAX_CHARS = 8000;
const BASE = 'https://pages.fm/api';

const get = (url, qs) => this.helpers.httpRequest({ method: 'GET', url, qs, json: true, timeout: 60000 });
const post = (url, qs) => this.helpers.httpRequest({ method: 'POST', url, qs, json: true, timeout: 60000 });

const toTs = (v) => {
  if (v == null) return NaN;
  if (typeof v === 'number') return v > 1e12 ? v / 1000 : v;
  const s = String(v);
  return Date.parse(/[zZ]|[+-]\d\d:?\d\d$/.test(s) ? s : s + 'Z') / 1000;
};
const clean = (s) => String(s || '')
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<[^>]+>/g, '')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/\n{3,}/g, '\n\n')
  .trim();
const hhmm = (ts) => new Date((ts + VN_OFFSET) * 1000).toISOString().slice(11, 16);

// Các trường liên quan SĐT / báo xấu / ghi chú mà Pancake trả về (nếu có),
// để AI dùng cho bộ lọc tình trạng số điện thoại.
const pickSignals = (obj, depth = 0, out = {}) => {
  if (!obj || typeof obj !== 'object' || depth > 3) return out;
  for (const [k, v] of Object.entries(obj)) {
    if (/phone|report|bom|boom|note|return|order_count|succe|fail|tag/i.test(k) && v != null && v !== '' &&
        !(Array.isArray(v) && v.length === 0)) {
      out[k] = v;
    } else if (typeof v === 'object') {
      pickSignals(v, depth + 1, out);
    }
  }
  return out;
};

// 1. Danh sách page
const pagesRes = await get(`${BASE}/v1/pages`, { access_token: token });
let pages = pagesRes?.categorized?.activated || pagesRes?.pages || pagesRes?.data || [];
const onlyPages = String(cfg.chi_quet_page_ids || '').split(',').map((s) => s.trim()).filter(Boolean);
if (onlyPages.length) pages = pages.filter((p) => onlyPages.includes(String(p.id)));
if (!pages.length) throw new Error('Pancake không trả về page nào. Kiểm tra lại access token. Phản hồi: ' + JSON.stringify(pagesRes).slice(0, 500));

const results = [];
const errors = [];

for (const page of pages) {
  const pageId = String(page.id);
  const pageName = page.name || pageId;
  let pageToken;
  try {
    const t = await post(`${BASE}/v1/pages/${pageId}/generate_page_access_token`, { page_id: pageId, access_token: token });
    pageToken = t?.page_access_token || t?.data?.page_access_token;
  } catch (e) {
    errors.push(`${pageName}: không tạo được page token (${e.message})`);
    continue;
  }
  if (!pageToken) { errors.push(`${pageName}: không có page token`); continue; }

  // 2. Hội thoại: lấy đến thời điểm hiện tại rồi lọc theo thời gian TẠO,
  // để không sót hội thoại tạo hôm qua nhưng có tin nhắn mới hôm nay.
  const convs = new Map();
  let lastId;
  for (let i = 0; i < 100; i++) {
    const qs = { page_access_token: pageToken, since, until: Math.floor(Date.now() / 1000), order_by: 'inserted_at' };
    if (lastId) qs.last_conversation_id = lastId;
    let res;
    try {
      res = await get(`${BASE}/public_api/v2/pages/${pageId}/conversations`, qs);
    } catch (e) {
      errors.push(`${pageName}: lỗi lấy hội thoại (${e.message})`);
      break;
    }
    const list = res?.conversations || res?.data || [];
    if (!list.length) break;
    for (const c of list) {
      const ts = toTs(c.inserted_at);
      if (ts >= since && ts < until) convs.set(String(c.id), c);
    }
    const newLast = String(list[list.length - 1].id);
    if (newLast === lastId) break;
    lastId = newLast;
  }

  // 3. Tin nhắn của từng hội thoại (5 luồng song song)
  const convList = [...convs.values()];
  for (let i = 0; i < convList.length; i += 5) {
    const chunk = convList.slice(i, i + 5);
    const done = await Promise.all(chunk.map(async (c) => {
      const customer = (c.customers || [])[0] || {};
      const qs = { page_access_token: pageToken };
      if (customer.id) qs.customer_id = customer.id;
      let res;
      try {
        res = await get(`${BASE}/public_api/v1/pages/${pageId}/conversations/${c.id}/messages`, qs);
      } catch (e) {
        errors.push(`${pageName}/${c.id}: lỗi lấy tin nhắn (${e.message})`);
        return null;
      }
      const msgs = (res?.messages || res?.data || [])
        .slice()
        .sort((a, b) => toTs(a.inserted_at) - toTs(b.inserted_at));
      let nKhach = 0;
      let nPage = 0;
      const lines = msgs.map((m) => {
        const fromPage = String(m.from?.id || '') === pageId || m.from?.admin_id != null || m.from?.page_id != null;
        fromPage ? nPage++ : nKhach++;
        let text = clean(m.original_message || m.message);
        const att = (m.attachments || []).map((a) => `[${a.type || 'tệp'}]`).join(' ');
        if (!text && !att && m.type) text = `[${m.type}]`;
        return `[${hhmm(toTs(m.inserted_at))}] ${fromPage ? 'PAGE' : 'KHÁCH'}: ${[text, att].filter(Boolean).join(' ')}`;
      });
      let transcript = lines.slice(-MAX_MSG).join('\n');
      if (transcript.length > MAX_CHARS) transcript = '…\n' + transcript.slice(-MAX_CHARS);
      if (lines.length > MAX_MSG) transcript = `(bỏ bớt ${lines.length - MAX_MSG} tin nhắn cũ)\n` + transcript;

      const signals = pickSignals({
        conversation: { recent_phone_numbers: c.recent_phone_numbers, tags: c.tags, has_phone: c.has_phone },
        customers: res?.customers,
        extra: { reports_by_phone: res?.reports_by_phone, notes: res?.notes, recent_orders: res?.recent_orders },
      });

      return {
        ngay: day,
        page_id: pageId,
        page_name: pageName,
        conversation_id: String(c.id),
        loai: c.type || '',
        khach_hang: customer.name || c.from?.name || '',
        so_tin_khach: nKhach,
        so_tin_page: nPage,
        link: `https://pancake.vn/${pageId}?c_id=${c.id}`,
        du_lieu_sdt: JSON.stringify(signals).slice(0, 1500),
        transcript: transcript || '(không có tin nhắn)',
      };
    }));
    for (const r of done) if (r) results.push(r);
  }
}

if (!results.length) {
  return [{ json: { _empty: true, ngay: day, so_page: pages.length, loi: errors.join(' | ') } }];
}
results[0].loi_lay_du_lieu = errors.join(' | ');
return results.map((json) => ({ json }));

// Ghép tiêu chí từ sheet "summary" + hội thoại thành các lô gửi Gemini.
const cfg = $('Cấu hình').first().json;
const leads = $input.all().map((i) => i.json);
if (leads.length === 1 && leads[0]._empty) return [];

// Bảng tiêu chí: cột A = tên bộ lọc (ô gộp, chỉ dòng đầu có giá trị), B = LEAD NGON, C = LEAD DỞ
const rows = $('Đọc tiêu chí (summary)').first().json.values || [];
const filters = [];
let cur = null;
for (const r of rows) {
  const [a, b, c] = [r[0], r[1], r[2]].map((v) => String(v || '').trim());
  if (a && (!cur || cur.name !== a)) {
    cur = { name: a, ngon: [], do: [] };
    filters.push(cur);
  }
  if (!cur) continue;
  if (b) cur.ngon.push(b);
  if (c) cur.do.push(c);
}
if (!filters.length) throw new Error('Sheet "summary" trống hoặc không đọc được.');
const criteria = filters
  .map((f) => `### ${f.name}\n${f.ngon.map((x) => '  + ' + x).join('\n')}\n${f.do.map((x) => '  - ' + x).join('\n')}`)
  .join('\n\n');
const filterNames = filters.map((f) => f.name);

const system = `Bạn là chuyên viên đánh giá chất lượng lead cho một doanh nghiệp bán NỆM qua Facebook/Pancake.
Nhiệm vụ: đọc từng hội thoại và chấm lead theo ĐÚNG bộ tiêu chí dưới đây (dòng "+" là dấu hiệu LEAD NGON, dòng "-" là dấu hiệu LEAD DỞ).

${criteria}

QUY TẮC:
- Chấm lần lượt TỪNG bộ lọc ở trên, giữ nguyên tên bộ lọc. Mỗi bộ lọc cho kết quả: "NGON", "DO" hoặc "KHONG_RO" (khi hội thoại và dữ liệu đi kèm không có thông tin để kết luận cho bộ lọc đó).
- Bộ lọc về số điện thoại: dùng mọi dấu hiệu có trong hội thoại (khách để lại SĐT, nhân viên nhắn "gọi không nghe máy", "thuê bao", "zalo chặn người lạ", "đã kết bạn zalo", "đã gọi tư vấn"...) và trường "Dữ liệu SĐT từ Pancake" (báo xấu, tỉ lệ hoàn, bom hàng...). Không có dấu hiệu nào thì ghi KHONG_RO, KHÔNG được đoán.
- Bộ lọc về hồ sơ FB/Zalo: chỉ kết luận khi có thông tin (tên nick kiểu clone, nội dung nhân viên nhắc tới...), còn lại KHONG_RO.
- Kết luận chung (ket_luan):
  * "DO" nếu bộ lọc số điện thoại (bộ lọc quyết định) là DO, hoặc có dấu hiệu "loại ngay" rõ ràng (hỏi sai sản phẩm, giá phi thực tế, chỉ 1 tin cụt lủn/sticker/tin nhắn mặc định của Facebook rồi im lặng...).
  * "NGON" nếu có nhu cầu thật và tương tác 2 chiều, không vướng dấu hiệu loại ngay.
  * "CHUA_RO" nếu quá ít thông tin để kết luận.
- nhom_ly_do: nhãn ngắn (tối đa 6 từ) cho lý do chính, dùng lại cách diễn đạt của bảng tiêu chí để các lead cùng lý do có cùng nhãn. Ví dụ: "Tin nhắn cụt, 1 chiều", "Giá không thực tế", "Hỏi sai sản phẩm", "SĐT không liên lạc được", "Có nhu cầu rõ ràng".
- ly_do: 1-2 câu tiếng Việt, dẫn chứng cụ thể từ hội thoại.
- nhu_cau: sản phẩm/kích thước/chất liệu khách hỏi (nếu có), để trống nếu không có.
- Trả về đúng MỘT phần tử cho MỖI hội thoại, giữ nguyên conversation_id.

ĐỊNH DẠNG TRẢ VỀ: chỉ một mảng JSON, không kèm chữ nào khác, không dùng \`\`\`:
[{"conversation_id":"...","ket_luan":"NGON|DO|CHUA_RO","bo_loc":[{"ten":"<tên bộ lọc>","ket_qua":"NGON|DO|KHONG_RO","ly_do":"..."}],"nhom_ly_do":"...","ly_do":"...","nhu_cau":"..."}]`;


const size = Math.max(1, Number(cfg.so_hoi_thoai_moi_lan_goi_ai) || 10);
const out = [];
for (let i = 0; i < leads.length; i += size) {
  const chunk = leads.slice(i, i + size);
  const text = chunk.map((l) => [
    `===== HỘI THOẠI conversation_id=${l.conversation_id} =====`,
    `Page: ${l.page_name} | Loại: ${l.loai || 'INBOX'} | Khách: ${l.khach_hang} | Số tin khách: ${l.so_tin_khach} | Số tin page: ${l.so_tin_page}`,
    `Dữ liệu SĐT từ Pancake: ${l.du_lieu_sdt && l.du_lieu_sdt !== '{}' ? l.du_lieu_sdt : '(không có)'}`,
    l.transcript,
  ].join('\n')).join('\n\n');

  out.push({
    json: {
      conversation_ids: chunk.map((l) => l.conversation_id),
      filter_names: filterNames,
      body: {
        systemInstruction: { parts: [{ text: system }] },
        contents: [{ role: 'user', parts: [{ text: `Chấm ${chunk.length} hội thoại sau:\n\n${text}` }] }],
        generationConfig: {
          temperature: 0.1,
          responseMimeType: 'application/json',
          maxOutputTokens: 16384,
          ...(/2\.5-flash/.test(cfg.gemini_model) ? { thinkingConfig: { thinkingBudget: 0 } } : {}),
        },
      },
    },
  });
}
return out;

// Ghép kết quả Gemini với thông tin hội thoại -> 1 dòng / lead cho tab BC_CHI_TIET.
const leads = new Map($('Lấy hội thoại Pancake').all().map((i) => [i.json.conversation_id, i.json]));
const batches = $('Chia lô gửi AI').all();
const responses = $input.all();
const label = { NGON: 'Ngon', DO: 'Dở', CHUA_RO: 'Chưa rõ', KHONG_RO: 'Không rõ' };
const updatedAt = new Date(Date.now() + 7 * 3600 * 1000).toISOString().slice(0, 16).replace('T', ' ');

const graded = new Map();
const batchError = new Map();
const parseJson = (text) => {
  const t = String(text || '').replace(/```(?:json)?/gi, '').trim();
  try { return JSON.parse(t); } catch (e) { /* thử cắt lấy mảng JSON */ }
  const a = t.indexOf('['), b = t.lastIndexOf(']');
  return a >= 0 && b > a ? JSON.parse(t.slice(a, b + 1)) : [];
};
responses.forEach((res, idx) => {
  const r = res.json;
  const ids = batches[idx]?.json.conversation_ids || [];
  let arr = [];
  let why = '';
  if (r.error) {
    why = `Gemini báo lỗi: ${r.error.message || JSON.stringify(r.error)}`.slice(0, 400);
  } else if (!r.candidates?.length) {
    why = `Gemini không trả nội dung${r.promptFeedback?.blockReason ? ' (bị chặn: ' + r.promptFeedback.blockReason + ')' : ''}`;
  } else {
    const text = (r.candidates[0].content?.parts || []).map((p) => p.text || '').join('');
    try {
      arr = parseJson(text);
      if (!Array.isArray(arr)) arr = Object.values(arr || {}).find(Array.isArray) || (arr?.conversation_id ? [arr] : []);
    } catch (e) { why = `Không đọc được JSON từ Gemini (finishReason: ${r.candidates[0].finishReason || '?'})`; }
  }
  ids.forEach((id) => why && batchError.set(String(id), why));
  for (const g of Array.isArray(arr) ? arr : []) {
    if (g && ids.includes(String(g.conversation_id))) graded.set(String(g.conversation_id), g);
  }
});

const out = [];
for (const [id, l] of leads) {
  if (!l.conversation_id) continue;
  const g = graded.get(id);
  out.push({
    json: {
      'Mã hội thoại': id,
      'Ngày': l.ngay,
      'Page': l.page_name,
      'Khách hàng': l.khach_hang,
      'Loại': l.loai,
      'Tin khách/page': `${l.so_tin_khach}/${l.so_tin_page}`,
      'Kết luận': g ? label[g.ket_luan] || g.ket_luan : 'Lỗi AI',
      'Nhóm lý do': g?.nhom_ly_do || '',
      'Lý do': g?.ly_do || (g ? '' : batchError.get(id) || 'Gemini không trả kết quả cho hội thoại này'),
      'Chi tiết bộ lọc': g ? (g.bo_loc || []).map((b) => `${b.ten}: ${label[b.ket_qua] || b.ket_qua} - ${b.ly_do}`).join('\n') : '',
      'Nhu cầu': g?.nhu_cau || '',
      'Link Pancake': l.link,
      'Cập nhật lúc': updatedAt,
      _bo_loc: g?.bo_loc || [],
    },
  });
}
return out;

// Tổng hợp 1 dòng thống kê / ngày cho tab BC_NGAY.
let rows = [];
try {
  rows = $('Tách kết quả AI').all().map((i) => i.json);
} catch (e) {
  rows = [];
}
const first = $('Lấy hội thoại Pancake').first().json;
const day = first.ngay;
const count = (arr, key) => arr.reduce((m, x) => {
  const k = key(x);
  if (k) m[k] = (m[k] || 0) + 1;
  return m;
}, {});
const top = (obj, n) => Object.entries(obj).sort((a, b) => b[1] - a[1]).slice(0, n).map(([k, v]) => `${k} (${v})`).join('; ');

const total = rows.length;
const by = count(rows, (r) => r['Kết luận']);
const ngon = by['Ngon'] || 0;
const dở = by['Dở'] || 0;

const filterDo = {};
for (const r of rows) {
  for (const b of r._bo_loc || []) {
    if (b.ket_qua === 'DO') filterDo[b.ten] = (filterDo[b.ten] || 0) + 1;
  }
}
const pages = {};
for (const r of rows) {
  const p = (pages[r['Page']] ||= { t: 0, n: 0 });
  p.t++;
  if (r['Kết luận'] === 'Ngon') p.n++;
}

return [{
  json: {
    'Ngày': day,
    'Tổng lead': total,
    'Lead ngon': ngon,
    'Lead dở': dở,
    'Chưa rõ': by['Chưa rõ'] || 0,
    'Lỗi AI': by['Lỗi AI'] || 0,
    'Tỉ lệ ngon (%)': total ? Math.round((ngon / total) * 1000) / 10 : 0,
    'Dở theo bộ lọc': Object.entries(filterDo).map(([k, v]) => `${k}: ${v}`).join('\n'),
    'Lý do dở phổ biến': top(count(rows.filter((r) => r['Kết luận'] === 'Dở'), (r) => r['Nhóm lý do']), 5),
    'Điểm cộng phổ biến': top(count(rows.filter((r) => r['Kết luận'] === 'Ngon'), (r) => r['Nhóm lý do']), 5),
    'Theo page': Object.entries(pages).map(([k, v]) => `${k}: ${v.n}/${v.t} ngon`).join('\n'),
    'Ghi chú': first._empty ? `Không có hội thoại mới. ${first.loi || ''}`.trim() : first.loi_lay_du_lieu || '',
    'Cập nhật lúc': new Date(Date.now() + 7 * 3600 * 1000).toISOString().slice(0, 16).replace('T', ' '),
  },
}];

// Chuẩn bị dòng ghi vào tab BC_CHI_TIET (chế độ: append).
// Khóa là cột A: dòng đã có khóa thì ghi đè đúng dòng đó, chưa có thì thêm mới.
const TAB = 'BC_CHI_TIET';
const MODE = 'append';
const HEADERS = ["Mã hội thoại","Ngày","Page","Khách hàng","Loại","Tin khách/page","Kết luận","Nhóm lý do","Lý do","Chi tiết bộ lọc","Nhu cầu","Link Pancake","Cập nhật lúc"];
let source = [];
try {
  source = $('Tách kết quả AI').all().map((i) => i.json);
} catch (e) {
  source = [];
}
const existing = ($('Đọc khóa BC_CHI_TIET').first().json.values || []).map((r) => String((r || [])[0] ?? '').trim());
const rowOf = new Map();
existing.forEach((k, i) => { if (i > 0 && k && !rowOf.has(k)) rowOf.set(k, i + 1); });

const toRow = (o) => HEADERS.map((h) => {
  const v = o[h];
  return v == null ? '' : typeof v === 'object' ? JSON.stringify(v) : v;
});

const updates = [];
const appends = [];
for (const o of source) {
  const key = String(o[HEADERS[0]] ?? '').trim();
  if (!key) continue;
  const r = rowOf.get(key);
  if (r) updates.push({ range: `${TAB}!A${r}`, values: [toRow(o)] });
  else appends.push(toRow(o));
}

if (MODE === 'update') {
  return updates.length ? [{ json: { body: { valueInputOption: 'RAW', data: updates } } }] : [];
}
return appends.length ? [{ json: { body: { values: appends } } }] : [];

// Chuẩn bị dòng ghi vào tab BC_CHI_TIET (chế độ: update).
// Khóa là cột A: dòng đã có khóa thì ghi đè đúng dòng đó, chưa có thì thêm mới.
const TAB = 'BC_CHI_TIET';
const MODE = 'update';
const HEADERS = ["Mã hội thoại","Ngày","Page","Khách hàng","Loại","Tin khách/page","Kết luận","Nhóm lý do","Lý do","Chi tiết bộ lọc","Nhu cầu","Link Pancake","Cập nhật lúc"];
let source = [];
try {
  source = $('Tách kết quả AI').all().map((i) => i.json);
} catch (e) {
  source = [];
}
const existing = ($('Đọc khóa BC_CHI_TIET').first().json.values || []).map((r) => String((r || [])[0] ?? '').trim());
const rowOf = new Map();
existing.forEach((k, i) => { if (i > 0 && k && !rowOf.has(k)) rowOf.set(k, i + 1); });

const toRow = (o) => HEADERS.map((h) => {
  const v = o[h];
